      a80: ['유리 구두를 지어 주신 날부터였을 거예요. 제 마음이 제독님 쪽으로 걸어간 건.', '저는 가진 게 없어요. 이 손과 이 마음뿐이에요. 그래도 받아 주신다면… 다 드릴게요.', '제독님이 부르시면, 열두 시가 지나도 마법이 풀려도 꼭 갈게요.']
