      { t: '벽의 거울', l: ['새 왕비님한테는 말하는 거울이 있었어요. 날마다 누가 제일 고운지 물어보셨대요.', '거울이 제 이름을 대던 날부터 왕비님 눈빛이 달라졌어요.', '저는 지금도 거울 앞에 오래 서 있지 않아요. 거울이 무슨 말을 할지 몰라서요.', '바다가 좋은 건, 물에 비친 얼굴은 금세 물결에 흩어지기 때문이에요.'] },
      { t: '일곱 광부의 오두막', l: ['숲속 깊이 작은 오두막이 있었어요. 접시도 일곱, 잔도 일곱, 침대도 일곱이요.', '배가 고파서 접시마다 조금씩 덜어 먹고, 일곱째 침대에서 잠들어 버렸어요.', '돌아온 아저씨들이 깜짝 놀랐지만, 살림을 맡아 주면 함께 살자고 하셨어요.', '그때 보석 다듬는 법이랑 장부 셈을 배웠어요. 사내들을 부리는 법도요!'] },
      { t: '끈과 빗과 사과', l: ['왕비님은 세 번이나 찾아오셨어요. 처음엔 장사꾼 할머니로 꾸미고 고운 끈을 팔러요.', '두 번째는 빗이었고, 세 번째가… 반쪽만 빨간 사과였어요.', '한 입 먹고 쓰러졌는데, 다들 제가 죽은 줄 알았대요.', '그래서 지금도 낯선 사람이 주는 사과는 안 먹어요. 아무리 빨개도요.'] },
      { t: '일곱이 된 날', l: ['사냥꾼에게 쫓겨 숲을 달릴 때, 이번엔 정말 끝인 줄 알았어요.', '그런데 제독님 일행이 칼을 뽑아 주셨죠. 다 끝나고 세어 보니 꼭 일곱 사람이었어요.', '오두막 아저씨들도 일곱이었으니까, 하늘이 다시 집을 보내 준 거라고 생각했어요.'] },
      { t: '거울이 못 보는 곳', l: ['왕비님 거울은 세상 끝까지 다 본대요. 그런데 바다 한가운데는 못 보나 봐요.', '여기 와서 처음으로 밤에 문을 안 잠그고 잤어요.', '제독님, 이 배가 제 오두막이에요. 오래오래 살림 맡을게요. 그러니까 손 씻고 오세요!'] }
