    again: ['또요? 그럼 섬 이야기 하나 더 해 드릴게요.', '좋아요. 이건 세랑 어른도 모르는 이야기예요.', '선장님은 이야기를 정향처럼 아껴 들으시네요.'],
    drink: ['한 잔만요. 정향을 한 알 띄워 주시면 두 잔도 돼요.', '야자술이면 좋아요. 테르나테 맛이에요.', '좋아요. 대신 건배는 말레이 말로 해요.'],
    drinkDone: '아까 마셨잖아요. 셈하는 사람이 취하면 정향 값이 틀려요.',
    lifeIntro: ['제 이야기요? 가말라마 산의 정향나무 한 그루부터 시작해야 해요.', '좋아요. 히투 해변에서 코라코라를 몰던 날부터요.'],
    stories: [
      { t: '할머니의 할머니의 나무', l: ['제가 태어난 날, 어머니가 가말라마 중턱에 정향나무를 심었대요.', '할머니의 할머니가 심은 나무 옆에요.', '어릴 때 그 나무가 마르는 해에 열병을 앓았어요. 다들 나무 탓이라고 했죠.', '나무가 다시 꽃을 피운 해에 저도 일어났어요. 그 뒤로 저는 나무를 믿어요.'] },
      { t: '흰 사람의 말', l: ['히투에서 모셔 온 흰 사람들은 말이 너무 빨랐어요.', '저는 세랑 어른 곁에서 한 단어씩 배웠어요. 「크라부」가 정향, 「노스 에스 마스」가 육두구.', '어른은 제 말레이 말 발음을 고쳐 주고, 저는 어른 포르투갈 말 셈을 고쳐 드렸어요.', '그래서 어른은 섬에서 제일 셈이 정확한 흰 사람이 되셨죠.'] },
      { t: '티도레의 섬', l: ['테르나테에서 바다 건너 손에 잡힐 듯한 데 티도레가 있어요.', '두 섬은 형제처럼 생겼는데, 원수처럼 싸워요. 정향 때문에요.', '흰 사람들이 오고 나서는 대포 때문에도 싸워요.', '저는 가끔 생각해요. 정향이 없었으면 두 섬은 사이좋았을까. 아마 그래도 싸웠겠죠.'] },
      { t: '마지막 편지', l: ['세랑 어른은 돌아가시기 사흘 전에 편지를 쓰셨어요.', '「페르낭이 오면, 섬의 왕들을 너무 믿지 말라고 전해 다오.」', '그 편지를 들고 수그부까지 갔는데, 그분은 다음 날 막탄의 여울에서 쓰러지셨어요.', '두 분이 한 해에 가셨어요. 서로를 만나지도 못하고요. 편지만 둘 사이를 오갔어요.'] },
      { t: '사러 오는 사람', l: ['섬의 어른들은 큰 배를 보면 「누가 사러 왔다」고 해요.', '그런데 언젠가부터 「누가 섬을 사려고 왔다」는 말이 들려요.', '한 글자 차이예요. 그런데 그 한 글자에 섬이 통째로 들어가요.', '선장님은 사러 온 사람이었어요. 처음부터요.'] }
    ]
