      { t: '두 임금', l: ['제가 궁에 있을 때 임금님이 둘이었어요. 달아난 형님과 남은 아우님.', '남은 아우님은 늘 인국공 나으리를 곁눈질하셨어요.', '마마께서는 두 아드님 이야기를 할 때면 염주만 돌리셨어요.', '어머니가 아들을 둘 다 잃는 데는 다섯 해밖에 안 걸렸어요.'] },
      { t: '부엌의 왕손', l: ['소종 임금님이 돌아가신 겨울, 마마께서 저를 부엌으로 부르셨어요.', '아궁이 앞에 그을음투성이 아이가 있었어요. 왕손님이셨어요.', '저는 왕손님께 불 때는 법을 가르쳐 드렸어요. 머슴 아이처럼 보이셔야 했으니까요.', '왕손님은 불을 참 잘 때셨어요. 임금이 되셔서도 그러실까요.'] },
      { t: '대모 빗', l: ['마마께서 마지막으로 주신 게 그 대모 빗이에요.', '「바다거북은 바다에서 왔으니, 바다로 돌아가거라」 하셨어요.', '그때는 무슨 말씀인지 몰랐어요.', '선장님 손에 빗을 쥐여 드릴 때, 그제야 알았어요.'] }
