      { t: '항주를 떠나던 날', l: ['명나라 백성이 나라 몰래 바다를 건너면 목이 달아납니다. 아버지께서도 잘 아셨습니다.', '그래도 저는 그 배를 놓칠 수 없었습니다. 평생 은하수 이쪽에 서 있을 수는 없었으니까요.', '부두를 떠날 때 뒤돌아보니, 무관 마당에 등불 하나가 오래 켜져 있었습니다.', '아버지께서 배웅해 주신 거라고 믿고 있습니다.'] },
      { t: '거북이 놓은 다리', l: ['한산도 혼례 날, 오작 할멈이 그러셨지요. 까치 대신 거북이가 다리를 놓았다고.', '저는 그날 맹세했습니다. 제 주먹은 이제 이 배와 제독을 위해 쓰겠다고.', '제독, 은혜는 말로 갚는 게 아닙니다. 이 주먹으로 갚겠습니다. 언제든 앞에 세워 주십시오!'] }
